contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address other, uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        require(other != address(this));

        // deposit for this contract
        c.fallback{value: amount}();
        // deposit for a different account
        c.fallback{value: amount}();
        // can't specify beneficiary; instead track this contract's own deposit only.

        uint balBefore = c.balances(address(this));
        uint etherBefore = address(c).balance;
        uint testBalBefore = address(this).balance;

        c.withdraw();

        uint balAfter = c.balances(address(this));
        uint etherAfter = address(c).balance;
        uint testBalAfter = address(this).balance;

        assert(balBefore == amount &&
               balAfter == 0 &&
               etherAfter == etherBefore - amount &&
               testBalAfter == testBalBefore + amount);
    }

    receive() external payable {}
}

