        uint balAfter = c.balances(address(this));
        uint otherAfter = c.balances(other);
        uint etherAfter = address(c).balance;
        uint testBalAfter = address(this).balance;

        assert(balBefore == amount &&
               balAfter == 0 &&
               otherBefore == amount &&
               otherAfter == otherBefore &&
               etherAfter == etherBefore - amount &&
               testBalAfter == testBalBefore + amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    bool rejectPayments;
    constructor(C _c) { c = _c; }

    function run(bool reject) public {
        rejectPayments = reject;

        uint etherBefore = address(c).balance;
        uint recordedBefore = c.balances(address(this));

        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }

        uint etherAfter = address(c).balance;
        uint recordedAfter = c.balances(address(this));

        assert(reverted == rejectPayments &&
               recordedAfter == recordedBefore &&
               etherAfter == etherBefore);
    }

    receive() external payable {
        if (rejectPayments) { revert(); }
    }
}
